COMPILER_BUILD_FILES = (
    'examples/hia_bootstrap/core_json_cli_packer.hiaasm',
)


PUBLICATION_BUILD_FILES = (
    'examples/hia_bootstrap/artifact_publication_policy.hiaasm',
